#include <regex>

std::string markdown_to_html(const std::string& md) {
    std::string html = md;
    // ---- headers ----
    html = std::regex_replace(html, std::regex("^### (.+)$", std::regex_constants::multiline), "<h3>$1</h3>");
    html = std::regex_replace(html, std::regex("^## (.+)$",  std::regex_constants::multiline), "<h2>$1</h2>");
    html = std::regex_replace(html, std::regex("^# (.+)$",   std::regex_constants::multiline), "<h1>$1</h1>");
    // ---- inline ----
    html = std::regex_replace(html, std::regex(R"(\*\*(.+?)\*\*)"), "<strong>$1</strong>");
    html = std::regex_replace(html, std::regex(R"(\*(.+?)\*)"),   "<em>$1</em>");
    html = std::regex_replace(html, std::regex(R"(\`(.+?)\`)"),   "<code>$1</code>");
    // ---- paragraphs ----
    html = std::regex_replace(html, std::regex("\n\n"), "</p>\n<p>");
    if (!html.empty() && html.front() != '<') html = "<p>" + html;
    if (!html.empty() && html.back()  != '>') html += "</p>";
    return html;
}

